public int knapsack(int[] w, int[] v, int cap, int n) {
  if (n == 0 || cap == 0) return 0;
  if (w[n-1] > cap) return knapsack(w, v, cap, n-1);
  return Math.max(v[n-1] + knapsack(w, v, cap-w[n-1], n-1),
                  knapsack(w, v, cap, n-1));
