public int countWaysDP(int n) {
  int[] dp = new int[n+1];
  dp[0] = 1;
  for (int i = 1; i <= n; i++) {
    if (i >= 1) dp[i] += dp[i-1];
    if (i >= 2) dp[i] += dp[i-2];
    if (i >= 3) dp[i] += dp[i-3];
  }
  return dp[n];
