public void subsetsHelper(int[] nums, int idx, List cur, List<List> res) {
  res.add(new ArrayList<>(cur));
  for (int i = idx; i < nums.length; i++) {
    cur.add(nums[i]);
    subsetsHelper(nums, i+1, cur, res);
    cur.remove(cur.size()-1);
  }
