  int[] dp = new int[n];
  Arrays.fill(dp, 1);
  for (int i = 1; i < n; i++)
    for (int j = 0; j < i; j++)
      if (arr[j] < arr[i]) dp[i] = Math.max(dp[i], dp[j]+1);
