public int robHouse(int[] nums) {
  if (nums.length == 0) return 0;
  int prev2 = 0, prev1 = 0;
  for (int num : nums) {
    int cur = Math.max(prev1, prev2 + num);
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
},1,1,False,Efficient

