public int longestConsecutive(int[] nums) {
  Set set = new HashSet<>();
  for (int n : nums) set.add(n);
  int maxLen = 0;
  for (int n : set)
    if (!set.contains(n-1)) {
      int cur = n, len = 1;
      while (set.contains(cur+1)) { cur++; len++; }
      maxLen = Math.max(maxLen, len);
    }
  return maxLen;
},2,2,False,Efficient

public int minCoinsRecursive(int[] coins, int amount) {
  if (amount == 0) return 0;
  int res = Integer.MAX_VALUE;
  for (int c : coins)
    if (c <= amount) {
      int sub = minCoinsRecursive(coins, amount - c);
      if (sub != Integer.MAX_VALUE) res = Math.min(res, sub + 1);
    }
  return res;
},1,1,True,Inefficient

